   ============================================================ */
.s-network .cols { display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: center; margin-top: 1.4rem; }
.net-scene { position: relative; height: 420px; }
.net-svg { width: 100%; height: 100%; overflow: visible; }
.net-svg .cell { fill: rgba(242,85,51,0.07); stroke: rgba(242,85,51,0.5); stroke-width: 1.5; }
.net-svg .cell-core { fill: var(--surface-floating); stroke: rgba(255,255,255,0.25); }
.net-svg .spoke { stroke: rgba(242,85,51,0.35); stroke-width: 1.2; stroke-dasharray: 3 5; }
.net-svg .up { stroke: rgba(255,255,255,0.28); stroke-width: 1.4; stroke-dasharray: 2 4; }
.net-svg text { fill: var(--text-muted); font-family: var(--font-mono); font-size: 11px; }
.net-svg .n-core-t { fill: var(--text); font-size: 13px; font-weight: 700; }
.net-svg .pulse { fill: none; stroke: var(--accent); stroke-width: 1.2; opacity: 0; transform-origin: center; transform-box: fill-box; }
.slide.active .net-svg .pulse { animation: net-pulse 3s ease-out infinite; animation-delay: calc(var(--i) * 0.9s); }
@keyframes net-pulse {
  0% { opacity: 0.75; transform: scale(0.6); }
  70% { opacity: 0; transform: scale(1.8); }
  100% { opacity: 0; transform: scale(1.8); }
}
.net-list { list-style: none; display: flex; flex-direction: column; gap: 0.55rem; margin-top: 1.6rem; }
.net-list li {
  display: flex; gap: 0.75rem; align-items: baseline;
  font-size: 0.95rem; color: var(--text-muted);
}
.net-list li::before { content: "▸"; color: var(--accent); font-size: 0.8em; }
.net-quote {
  margin-top: 2rem; padding-left: 1.2rem; border-left: 3px solid var(--accent);
  font-family: var(--font-headline); font-style: italic; font-weight: 540;
  font-size: clamp(1.05rem, 1.5vw, 1.35rem); color: var(--text); line-height: 1.4;
}
.preview-chip { margin-left: 0.8rem; vertical-align: middle; font-size: 0.62rem; }

/* ============================================================
   Slide 21 — principles
   ============================================================ */
.princ-list { list-style: none; margin-top: 2.4rem; columns: 2; column-gap: 3.5rem; }
.princ-list li {
  break-inside: avoid;
  font-family: var(--font-headline); font-weight: 560;
  font-size: clamp(1.1rem, 1.7vw, 1.55rem);
  line-height: 1.32;
  padding: 0.62rem 0;
  color: var(--text-muted);
  display: flex; gap: 0.9rem; align-items: baseline;
}
.princ-list li .n {
  font-family: var(--font-mono); font-size: 0.62em; font-weight: 700;
  color: var(--accent); flex: none; letter-spacing: 0.05em;
}
.princ-list li strong { color: var(--text); font-weight: 620; }

/* ============================================================
   Slide 22 — CTA
   ============================================================ */
.s-cta .cols { display: grid; grid-template-columns: 1fr 1.1fr; gap: 3.2rem; align-items: center; }
.cta-term { font-size: 0.78rem; }
.cta-term .term-body { min-height: 0; }
.cta-list { list-style: none; display: grid; grid-template-columns: 1fr; gap: 0.55rem; margin-top: 2rem; }
.cta-list li {
  display: flex; gap: 0.8rem; align-items: baseline;
  font-size: 0.98rem; color: var(--text-muted);
}
.cta-list li::before { content: "□"; font-family: var(--font-mono); color: var(--accent); }
.cta-list li strong { color: var(--text); font-weight: 560; }

/* ============================================================
   Slide 23 — closing
   ============================================================ */
.s-close { text-align: center; }
.s-close .marvin {
  width: 108px; margin: 0 auto 2.2rem; display: block;
  filter: drop-shadow(0 10px 30px rgba(242,85,51,0.25));
}
.close-quote {
  font-family: var(--font-headline); font-weight: 560; font-style: italic;
  font-size: clamp(1.2rem, 2vw, 1.75rem);
  color: var(--text-muted); line-height: 1.45;
  max-width: 46ch; margin: 0 auto; text-wrap: balance;
}
.close-quote strong { color: var(--text); font-style: italic; }
.close-beats { margin-top: 3.4rem; display: flex; flex-direction: column; gap: 0.35rem; }
.close-beats span {
  font-family: var(--font-headline); font-weight: 660;
  font-size: clamp(1.7rem, 3.2vw, 3rem);
  line-height: 1.15;
}
.close-beats span:last-child { color: var(--accent); }
.close-logo { width: 130px; margin: 3.4rem auto 0; opacity: 0.85; display: block; }

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; animation-delay: 0s !important; transition-duration: 0.01ms !important; }
  .stage-glow { animation: none; }
  [data-animate], .slide.active [data-animate] { opacity: 1; animation: none; }
  .slide.active .prog-step, .slide.active .term-body .ln { opacity: 1; animation: none; }
}

/* ============================================================
   Smaller screens
   ============================================================ */
@media (max-width: 1100px) {
  .slide { padding: 3rem 2.5rem 4rem; }
  .cap-grid { grid-template-columns: repeat(2, 1fr); }
  .agent-row { grid-template-columns: repeat(3, 1fr); }
  .s-forgot .cols, .s-knowledge .cols, .s-git .cols, .s-cta .cols, .s-network .cols { grid-template-columns: 1fr; gap: 2rem; }
  .prim-grid { grid-template-columns: 1fr; }
  .princ-list { columns: 1; }
  .runner-row { grid-template-columns: 1fr; gap: 0.3rem; }
  .verdict { justify-self: start; }
}

/* Entire deck — navigation, fragments, hash routing */
(() => {
  const slides = Array.from(document.querySelectorAll(".slide"));
  const progress = document.getElementById("progress");
  const hudCounter = document.getElementById("hudCounter");
  const hudAct = document.getElementById("hudAct");
  const total = slides.length;
  let current = -1;

  const clamp = (n) => Math.max(0, Math.min(total - 1, n));

  function fragmentsOf(slide) {
    return Array.from(slide.querySelectorAll("[data-fragment]"));
  }

  function show(n, { revealAll = false } = {}) {
    n = clamp(n);
    if (n === current) return;
    const prev = slides[current];
    if (prev) {
      prev.classList.remove("active");
      // reset fragments so re-entering replays them
      fragmentsOf(prev).forEach((f) => f.classList.remove("revealed"));
    }
    current = n;
    const slide = slides[n];
    // force animation restart: reflow between class removal and re-add
    void slide.offsetWidth;
    slide.classList.add("active");
    if (revealAll) fragmentsOf(slide).forEach((f) => f.classList.add("revealed"));

    progress.style.width = `${((n + 1) / total) * 100}%`;
    hudCounter.textContent = `${String(n + 1).padStart(2, "0")} / ${total}`;
    const act = slide.dataset.act || "";
    hudAct.innerHTML = act ? act.replace(/^(Act \d+)/, "<em>$1</em>") : "";
    history.replaceState(null, "", `#${n + 1}`);
  }

  function next() {
    const pending = fragmentsOf(slides[current]).find((f) => !f.classList.contains("revealed"));
    if (pending) { pending.classList.add("revealed"); return; }
    show(current + 1);
  }

  function back() {
    const revealed = fragmentsOf(slides[current]).filter((f) => f.classList.contains("revealed"));
    if (revealed.length) { revealed[revealed.length - 1].classList.remove("revealed"); return; }
    // going backwards: land with fragments already revealed
    show(current - 1, { revealAll: true });
  }

  document.addEventListener("keydown", (e) => {
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowDown":
      case " ":
      case "PageDown":
        e.preventDefault(); next(); break;
      case "ArrowLeft":
      case "ArrowUp":
      case "PageUp":
        e.preventDefault(); back(); break;
      case "Home":
        e.preventDefault(); show(0); break;
      case "End":
        e.preventDefault(); show(total - 1); break;
      case "f":
      case "F":
        toggleFullscreen(); break;
    }
  });

  function toggleFullscreen() {
    if (document.fullscreenElement) document.exitFullscreen();
    else document.documentElement.requestFullscreen().catch(() => {});
  }

  // click left/right thirds to navigate (ignore clicks on links)
  document.addEventListener("click", (e) => {
    if (e.target.closest("a, button")) return;
    const x = e.clientX / window.innerWidth;
    if (x > 0.72) next();
    else if (x < 0.28) back();
  });

  // touch swipe
  let touchX = null;
  document.addEventListener("touchstart", (e) => { touchX = e.touches[0].clientX; }, { passive: true });
  document.addEventListener("touchend", (e) => {
    if (touchX === null) return;
    const dx = e.changedTouches[0].clientX - touchX;
    if (Math.abs(dx) > 48) (dx < 0 ? next() : back());
    touchX = null;
  }, { passive: true });

  // respond to manual hash edits
  window.addEventListener("hashchange", () => {
    const n = parseInt(location.hash.slice(1), 10);
    if (!Number.isNaN(n)) show(n - 1);
  });

  // start at hash or 0
  const start = parseInt(location.hash.slice(1), 10);
  show(Number.isNaN(start) ? 0 : start - 1);
})();

